module axis_adapter #
(
    parameter S_DATA_WIDTH = 8,
    parameter S_KEEP_ENABLE = (S_DATA_WIDTH>8),
    parameter S_KEEP_WIDTH = ((S_DATA_WIDTH+7)/8),
    parameter M_DATA_WIDTH = 8,
    parameter M_KEEP_ENABLE = (M_DATA_WIDTH>8),
    parameter M_KEEP_WIDTH = ((M_DATA_WIDTH+7)/8),
    parameter ID_ENABLE = 0,
    parameter ID_WIDTH = 8,
    parameter DEST_ENABLE = 0,
    parameter DEST_WIDTH = 8,
    parameter USER_ENABLE = 1,
    parameter USER_WIDTH = 1
)
(
    input  wire                     clk,
    input  wire                     rst,
    /*
     * AXI input
     */
    input  wire [S_DATA_WIDTH-1:0]  s_axis_tdata,
    input  wire [S_KEEP_WIDTH-1:0]  s_axis_tkeep,
    input  wire                     s_axis_tvalid,
    output wire                     s_axis_tready,
    input  wire                     s_axis_tlast,
    input  wire [ID_WIDTH-1:0]      s_axis_tid,
    input  wire [DEST_WIDTH-1:0]    s_axis_tdest,
    input  wire [USER_WIDTH-1:0]    s_axis_tuser,
    /*
     * AXI output
     */
    output wire [M_DATA_WIDTH-1:0]  m_axis_tdata,
    output wire [M_KEEP_WIDTH-1:0]  m_axis_tkeep,
    output wire                     m_axis_tvalid,
    input  wire                     m_axis_tready,
    output wire                     m_axis_tlast,
    output wire [ID_WIDTH-1:0]      m_axis_tid,
    output wire [DEST_WIDTH-1:0]    m_axis_tdest,
    output wire [USER_WIDTH-1:0]    m_axis_tuser
);

    // Internal parameters
    localparam S_BYTES = (S_DATA_WIDTH + 7) / 8;
    localparam M_BYTES = (M_DATA_WIDTH + 7) / 8;
    localparam S_KEEP_W = S_KEEP_WIDTH;
    localparam M_KEEP_W = M_KEEP_WIDTH;

    // State machine
    localparam ST_IDLE = 2'd0;
    localparam ST_SEND = 2'd1;
    localparam ST_WAIT = 2'd2;

    reg [1:0] state;
    reg [S_DATA_WIDTH-1:0] data_buf;
    reg [S_KEEP_WIDTH-1:0] keep_buf;
    reg tlast_buf;
    reg [ID_WIDTH-1:0] id_buf;
    reg [DEST_WIDTH-1:0] dest_buf;
    reg [USER_WIDTH-1:0] user_buf;

    // Byte offset within the current input beat
    reg [3:0] byte_offset;
    reg [3:0] bytes_remaining;

    // Output data and keep
    reg [M_DATA_WIDTH-1:0] out_data;
    reg [M_KEEP_WIDTH-1:0] out_keep;
    reg out_tlast;

    // Helper: count set bits in keep
    function integer count_ones;
        input [S_KEEP_WIDTH-1:0] vec;
        integer i;
        begin
            count_ones = 0;
            for (i = 0; i < S_KEEP_WIDTH; i = i + 1) begin
                if (vec[i]) count_ones = count_ones + 1;
            end
        end
    endfunction

    // Helper: extract byte from input data at given byte index
    function [7:0] get_input_byte;
        input [S_DATA_WIDTH-1:0] data;
        input [3:0] byte_idx;
        begin
            get_input_byte = data[byte_idx*8 +: 8];
        end
    endfunction

    // Helper: set byte in output data at given byte index
    function [M_DATA_WIDTH-1:0] set_output_byte;
        input [M_DATA_WIDTH-1:0] data;
        input [3:0] byte_idx;
        input [7:0] byte_val;
        begin
            set_output_byte = data;
            set_output_byte[byte_idx*8 +: 8] = byte_val;
        end
    endfunction

    // Helper: set keep bit
    function [M_KEEP_WIDTH-1:0] set_keep_bit;
        input [M_KEEP_WIDTH-1:0] keep;
        input [3:0] byte_idx;
        begin
            set_keep_bit = keep;
            set_keep_bit[byte_idx] = 1'b1;
        end
    endfunction

    // Determine how many bytes are valid in current input beat
    wire [3:0] valid_bytes = count_ones(s_axis_tkeep);

    // Determine how many bytes are valid in buffered input beat
    wire [3:0] buf_valid_bytes = count_ones(keep_buf);

    // Output ready signal
    assign s_axis_tready = (state == ST_IDLE) && !rst;

    // Output signals
    assign m_axis_tdata = out_data;
    assign m_axis_tkeep = out_keep;
    assign m_axis_tvalid = (state == ST_SEND) && !rst;
    assign m_axis_tlast = out_tlast;
    assign m_axis_tid = id_buf;
    assign m_axis_tdest = dest_buf;
    assign m_axis_tuser = user_buf;

    // Main state machine
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= ST_IDLE;
            data_buf <= {S_DATA_WIDTH{1'b0}};
            keep_buf <= {S_KEEP_WIDTH{1'b0}};
            tlast_buf <= 1'b0;
            id_buf <= {ID_WIDTH{1'b0}};
            dest_buf <= {DEST_WIDTH{1'b0}};
            user_buf <= {USER_WIDTH{1'b0}};
            byte_offset <= 4'd0;
            bytes_remaining <= 4'd0;
            out_data <= {M_DATA_WIDTH{1'b0}};
            out_keep <= {M_KEEP_WIDTH{1'b0}};
            out_tlast <= 1'b0;
        end else begin
            case (state)
                ST_IDLE: begin
                    if (s_axis_tvalid) begin
                        // Capture input beat
                        data_buf <= s_axis_tdata;
                        keep_buf <= s_axis_tkeep;
                        tlast_buf <= s_axis_tlast;
                        id_buf <= s_axis_tid;
                        dest_buf <= s_axis_tdest;
                        user_buf <= s_axis_tuser;
                        byte_offset <= 4'd0;
                        bytes_remaining <= valid_bytes;
                        state <= ST_SEND;
                    end
                end

                ST_SEND: begin
                    if (m_axis_tready) begin
                        // Check if we've sent all bytes from current input beat
                        if (bytes_remaining == 4'd0) begin
                            // Done with this input beat
                            if (tlast_buf) begin
                                // End of packet, go back to idle
                                state <= ST_IDLE;
                            end else begin
                                // Wait for next input beat
                                state <= ST_WAIT;
                            end
                        end else begin
                            // More bytes to send from current beat
                            // Prepare next output beat
                            state <= ST_SEND;
                        end
                    end
                end

                ST_WAIT: begin
                    if (s_axis_tvalid) begin
                        // Capture new input beat
                        data_buf <= s_axis_tdata;
                        keep_buf <= s_axis_tkeep;
                        tlast_buf <= s_axis_tlast;
                        id_buf <= s_axis_tid;
                        dest_buf <= s_axis_tdest;
                        user_buf <= s_axis_tuser;
                        byte_offset <= 4'd0;
                        bytes_remaining <= valid_bytes;
                        state <= ST_SEND;
                    end
                end

                default: begin
                    state <= ST_IDLE;
                end
            endcase
        end
    end

    // Generate output data and keep
    always @(*) begin
        out_data = {M_DATA_WIDTH{1'b0}};
        out_keep = {M_KEEP_WIDTH{1'b0}};
        out_tlast = 1'b0;

        if (state == ST_SEND) begin
            // Determine how many bytes to pack into this output beat
            integer i;
            integer out_byte_idx;
