                // For now, let's just pass through if widths match
                if (S_DATA_WIDTH == M_DATA_WIDTH) begin
                    if (i < S_BYTES) begin
                        if (keep_buf[i]) begin
                            out_data[i*8 +: 8] = data_buf[i*8 +: 8];
                            out_keep[i] = 1'b1;
                        end
                    end
                end else begin
