            // For simplicity, let's set tlast when bytes_remaining equals the number of bytes in this output beat
            // and tlast_buf is set
            if (tlast_buf && (bytes_remaining <= M_BYTES)) begin
                out_tlast = 1'b1;
            end
        end
    end

    // Update byte_offset and bytes_remaining
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            byte_offset <= 4'd0;
            bytes_remaining <= 4'd0;
        end else begin
            case (state)
                ST_IDLE: begin
                    if (s_axis_tvalid) begin
                        byte_offset <= 4'd0;
                        bytes_remaining <= valid_bytes;
                    end
                end
                ST_SEND: begin
                    if (m_axis_tready) begin
                        // Calculate how many bytes were sent in this output beat
                        // This depends on the width conversion logic
                        // For now, assume we send min(M_BYTES, bytes_remaining) bytes
                        if (bytes_remaining >= M_BYTES) begin
