                            bytes_remaining <= bytes_remaining - M_BYTES;
                        end else begin
                            byte_offset <= byte_offset + bytes_remaining;
                            bytes_remaining <= 4'd0;
                        end
                    end
                end
                ST_WAIT: begin
                    if (s_axis_tvalid) begin
                        byte_offset <= 4'd0;
